 if(p.derivedRiskCandidates?.length)extra+='<details><summary>Additional risks suggested from the BOQ · '+fmt(p.derivedRiskCandidates.length)+'</summary>'+deliveryTable('derivedRisks','Suggested risks',p.derivedRiskCandidates,[['description','Risk'],['impact','Potential effect'],['mitigation','Suggested response'],['basis','Basis']])+'</details>';
